const RACE_BY_ID = Object.fromEntries(RACES.map(r => [r.id, r]));

function raceOf(raceId, subraceId) {
  const race = RACE_BY_ID[raceId];
  if (!race) return null;
  const sub = race.subraces?.find(s => s.id === subraceId) || null;
  return { race, sub };
}

// Сумма расовых бонусов к характеристикам
function racialBonuses(raceId, subraceId, flexible = []) {
  const found = raceOf(raceId, subraceId);
  const out = { str: 0, dex: 0, con: 0, int: 0, wis: 0, cha: 0 };
  if (!found) return out;
  for (const [k, v] of Object.entries(found.race.asi || {})) out[k] += v;
  for (const [k, v] of Object.entries(found.sub?.asi || {})) out[k] += v;
  if (found.race.asiFlexible) {
    for (const k of flexible.slice(0, found.race.asiFlexible)) if (out[k] !== undefined) out[k] += 1;
  }
  return out;
}

function raceName(raceId, subraceId) {
  const found = raceOf(raceId, subraceId);
  if (!found) return '—';
  return found.sub ? `${found.race.name} (${found.sub.name})` : found.race.name;
}

function raceSpeed(raceId, subraceId) {
  const found = raceOf(raceId, subraceId);
  if (!found) return 30;
  if (subraceId === 'wood-elf') return 35;
  return found.race.speed;
}

