const CLASS_BY_ID = Object.fromEntries(CLASSES.map(c => [c.id, c]));

// Все подклассы класса: новый формат `subclasses`, старый — одиночный `subclass`
function subclassesOf(cls) {
  if (!cls) return [];
  if (Array.isArray(cls.subclasses)) return cls.subclasses;
  return cls.subclass ? [cls.subclass] : [];
}

// Подкласс по идентификатору; если не выбран — первый доступный
function subclassOf(cls, subclassId) {
  const list = subclassesOf(cls);
  return list.find(s => s.id === subclassId) || list[0] || null;
}

function classFeatures(cls, level, subclassId) {
  const own = (cls.features || []).filter(f => f.level <= level);
  const sub = subclassOf(cls, subclassId);
  const subFeatures = (sub?.features || []).filter(f => f.level <= level);
  return { own, sub: subFeatures };
}

function spellSlots(cls, level) {
  const sc = cls.spellcasting;
  if (!sc) return [];
  const row = CASTER_SLOTS[sc.progression]?.[level] || [];
  return row.slice();
}

function maxSpellLevel(cls, level) {
  const sc = cls.spellcasting;
  if (!sc) return 0;
  if (sc.progression === 'pact') return PACT_MAGIC[level] || 1;
  const slots = spellSlots(cls, level);
  return slots.length;
}

function cantripsKnown(cls, level) {
  const arr = cls.spellcasting?.cantrips;
  return arr ? arr[level - 1] || 0 : 0;
}

function spellsKnownCount(cls, level) {
  const sc = cls.spellcasting;
  if (!sc || sc.kind !== 'known' || !sc.known) return null;
  return sc.known[level - 1] || 0;
}

