function spellsForClass(classId, maxLevel = 5) {
  const key = CLASS_KEY_BY_CLASS_ID[classId];
  if (!key) return [];
  return SPELLS.filter(s => s.classes.includes(key) && s.level <= maxLevel);
}

function spellsByLevel(list) {
  const out = {};
  for (const s of list) (out[s.level] ||= []).push(s);
  return out;
}

function spellName(id) {
  return SPELL_BY_ID[id]?.name || id;
}

